shader_type canvas_item;

void fragment() {
	vec3 teal = vec3(0.37, 0.64, 0.57);
	vec3 pale = vec3(0.95);
	vec3 c;
	if (UV.x < 0.5) {
		c = teal;
	} else {
		c = pale;
	}
	COLOR = vec4(c, 1.0);
}

shader_type canvas_item;

void fragment() {
	vec3 c = vec3(0.95);
	for (int i = 0; i < 5; i++) {
		float y = 0.1 + 0.2 * float(i);
		if (abs(UV.y - y) < 0.03) {
			c = vec3(0.37, 0.64, 0.57);
		}
	}
	COLOR = vec4(c, 1.0);
}
